'use strict';

// MODULES //

var tape = require( 'tape' );
var getPropertyDescriptor = require( '@stdlib/utils/property-descriptor' );
var getPrototypeOf = require( '@stdlib/utils/get-prototype-of' );
var parseJSON = require( '@stdlib/utils/parse-json' );
var convert = require( './../lib' );
var validateDocument = require( './../lib/validate_document.js' );


// FUNCTIONS //

/**
* Returns all semantic nodes matching a type.
*
* @private
* @param {Array} children - semantic nodes
* @param {string} type - node type
* @returns {Array} matching semantic nodes
*/
function findNodes( children, type ) {
	var out = [];
	var i;

	for ( i = 0; i < children.length; i++ ) {
		if ( children[ i ].type === type ) {
			out.push( children[ i ] );
		}
		if ( children[ i ].children ) {
			out = out.concat( findNodes( children[ i ].children, type ) );
		}
	}
	return out;
}

/**
* Returns the first semantic section matching a role.
*
* @private
* @param {Array} children - semantic nodes
* @param {string} role - section role
* @returns {(Object|null)} matching section or null
*/
function findSection( children, role ) {
	var sections;
	var i;

	sections = findNodes( children, 'section' );
	for ( i = 0; i < sections.length; i++ ) {
		if ( sections[ i ].role === role ) {
			return sections[ i ];
		}
	}
	return null;
}

/**
* Returns the first accounting record matching a classification.
*
* @private
* @param {Object} doc - semantic document
* @param {string} classification - accounting classification
* @returns {(Object|null)} matching record or null
*/
function findAccounting( doc, classification ) {
	var i;

	for ( i = 0; i < doc.accounting.length; i++ ) {
		if ( doc.accounting[ i ].classification === classification ) {
			return doc.accounting[ i ];
		}
	}
	return null;
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof convert, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function safely indexes reserved property names', function test( t ) {
	var markdown;
	var links;
	var index;
	var ast;
	var doc;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'[__proto__]: https://a',
		'[constructor]: https://b',
		'[toString]: https://c',
		'',
		'[a][__proto__] [b][constructor] [c][toString]'
	].join( '\n' );
	doc = convert( markdown );

	index = doc.resources.definitionIndex;
	t.strictEqual( getPropertyDescriptor( index, '__proto__' ).value, 'definition[0]', 'indexes __proto__' );
	t.strictEqual( index.constructor, 'definition[1]', 'indexes constructor' );
	t.strictEqual( index.tostring, 'definition[2]', 'indexes toString' );

	ast = findNodes( doc.children, 'markdown' )[ 0 ].ast;
	links = ast.children[ 0 ].children;
	t.strictEqual( links[ 0 ].url, 'https://a', 'resolves __proto__' );
	t.strictEqual( links[ 2 ].url, 'https://b', 'resolves constructor' );
	t.strictEqual( links[ 4 ].url, 'https://c', 'resolves toString' );
	t.end();
});

tape( 'the function safely parses reserved run directive keys', function test( t ) {
	var directive;
	var markdown;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'<!-- run: __proto__: true, constructor: 1 -->',
		'',
		'```javascript',
		'1',
		'```'
	].join( '\n' );
	directive = convert( markdown ).resources.directives[ 0 ];

	t.strictEqual( getPrototypeOf( directive.parsed ), null, 'uses a null prototype' );
	t.strictEqual( getPropertyDescriptor( directive.parsed, '__proto__' ).value, true, 'parses __proto__' );
	t.strictEqual( directive.parsed.constructor, 1, 'parses constructor' );
	t.end();
});

tape( 'ESLint directives apply only to the immediately following code block', function test( t ) {
	var directive;
	var markdown;
	var code;
	var doc;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'<!-- eslint-disable no-undef -->',
		'',
		'```javascript',
		'foo;',
		'```',
		'',
		'```javascript',
		'bar;',
		'```'
	].join( '\n' );
	doc = convert( markdown );
	directive = doc.resources.directives[ 0 ];
	code = findNodes( doc.children, 'code' );

	t.strictEqual( directive.scope, 'next-code', 'sets next-code scope' );
	t.deepEqual( code[ 0 ].directiveRefs, [ directive.id ], 'attaches the directive to the next code block' );
	t.deepEqual( code[ 1 ].directiveRefs, [], 'does not attach the directive to a later code block' );
	t.deepEqual( directive.targetRefs, [ code[ 0 ].id ], 'records only the next code block as a target' );
	t.end();
});

tape( 'the function ensures directive semantics contribute to code identity and accounting', function test( t ) {
	var secondCode;
	var firstCode;
	var prefix;
	var suffix;
	var second;
	var record;
	var first;

	prefix = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'<!-- run: timeout: '
	].join( '\n' );
	suffix = [
		' -->',
		'',
		'```javascript',
		'1',
		'```'
	].join( '\n' );
	first = convert( prefix+'1'+suffix );
	second = convert( prefix+'2'+suffix );
	firstCode = findNodes( first.children, 'code' )[ 0 ];
	secondCode = findNodes( second.children, 'code' )[ 0 ];
	record = findAccounting( first, 'run' );

	t.notEqual( firstCode.semanticHash, secondCode.semanticHash, 'changes the semantic hash' );
	t.deepEqual( record.targetRefs, [ 'directive[0]', firstCode.id ], 'accounts for the directive and code targets' );
	t.end();
});

tape( 'the function recovers a section at its matching end marker', function test( t ) {
	var markdown;
	var examples;
	var usage;
	var doc;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'<section class="usage">',
		'',
		'## Usage',
		'',
		'Text.',
		'',
		'<!-- /.usage -->',
		'',
		'<section class="examples">',
		'',
		'## Examples',
		'',
		'Text.',
		'',
		'</section>',
		'',
		'<!-- /.examples -->'
	].join( '\n' );
	doc = convert( markdown );
	examples = findSection( doc.children, 'examples' );
	usage = findSection( doc.children, 'usage' );

	t.strictEqual( usage.recovered, true, 'marks the section as recovered' );
	t.strictEqual( examples.id, 'section[examples:0]', 'keeps the next section as a sibling' );
	t.ok( findAccounting( doc, 'section-end' ), 'accounts for the recovery marker' );
	t.end();
});

tape( 'the function preserves mismatched section end markers', function test( t ) {
	var markdown;
	var doc;
	var raw;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'<section class="usage">',
		'',
		'Text.',
		'',
		'<!-- /.examples -->',
		'',
		'</section>',
		'',
		'<!-- /.usage -->'
	].join( '\n' );
	doc = convert( markdown );
	raw = findNodes( doc.children, 'raw' )[ 0 ];

	t.strictEqual( raw.value, '<!-- /.examples -->', 'preserves the marker' );
	t.strictEqual( raw.classification, 'mismatched-section-end-comment', 'classifies the mismatch' );
	t.deepEqual( findAccounting( doc, 'raw' ).targetRefs, [ raw.id ], 'accounts for the marker' );
	t.end();
});

tape( 'the "readme" profile preserves unmatched equation and image markup', function test( t ) {
	var markdown;
	var raws;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'<!-- <equation label="x"> -->',
		'',
		'Text.',
		'',
		'<!-- <img src="x.png"> -->'
	].join( '\n' );
	raws = findNodes( convert( markdown ).children, 'raw' );

	t.strictEqual( raws.length, 2, 'creates two raw nodes' );
	t.strictEqual( raws[ 0 ].classification, 'orphan-equation-wrapper', 'preserves the equation wrapper' );
	t.strictEqual( raws[ 1 ].value, '<!-- <img src="x.png"> -->', 'preserves the commented image' );
	t.end();
});

tape( 'the "generic" profile preserves standalone HTML comments', function test( t ) {
	var markdown;
	var raws;
	var doc;

	markdown = [
		'<!--',
		'',
		'@license Apache-2.0',
		'',
		'-->',
		'',
		'<!-- Package usage. -->',
		'',
		'<!-- run-disable -->',
		'',
		'<section class="usage">',
		'',
		'Text.',
		'',
		'</section>'
	].join( '\n' );
	doc = convert( markdown, {
		'profile': 'generic'
	});
	raws = findNodes( doc.children, 'raw' );

	t.strictEqual( raws.length, 5, 'preserves all standalone HTML' );
	t.strictEqual( findNodes( doc.children, 'section' ).length, 0, 'does not infer README sections' );
	t.strictEqual( doc.resources.directives.length, 0, 'does not infer README directives' );
	t.end();
});

tape( 'the function only removes balanced generated related spans', function test( t ) {
	var markdown;
	var value;
	var ast;
	var doc;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'<section class="related">',
		'',
		'## See Also',
		'',
		'- <span class="package-name">a</span><span class="other">b</span>',
		'',
		'</section>',
		'',
		'<!-- /.related -->'
	].join( '\n' );
	doc = convert( markdown );
	ast = findNodes( doc.children, 'markdown' )[ 0 ].ast;
	value = JSON.stringify( ast );

	t.strictEqual( value.indexOf( 'package-name' ), -1, 'removes a generated wrapper' );
	t.notEqual( value.indexOf( 'class=\\"other\\"' ), -1, 'preserves an unknown wrapper' );
	t.notEqual( value.indexOf( '</span>' ), -1, 'preserves its balanced close' );
	t.end();
});

tape( 'the function ensures single-node source hashes agree across document views', function test( t ) {
	var markdown;
	var record;
	var code;
	var doc;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'```javascript',
		'1',
		'```'
	].join( '\n' );
	doc = convert( markdown );
	record = findAccounting( doc, 'code' );
	code = findNodes( doc.children, 'code' )[ 0 ];

	t.strictEqual( code.sourceHash, code.source.refs[ 0 ].sourceHash, 'matches node provenance' );
	t.strictEqual( code.sourceHash, record.sourceHash, 'matches source accounting' );
	t.end();
});

tape( 'the function moves nested definitions to resources', function test( t ) {
	var markdown;
	var record;
	var value;
	var doc;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'- [inside]: https://example.com',
		'',
		'  [link][inside]'
	].join( '\n' );
	doc = convert( markdown );
	record = findAccounting( doc, 'definition' );
	value = JSON.stringify( findNodes( doc.children, 'markdown' )[ 0 ].ast );

	t.strictEqual( doc.resources.definitions.length, 1, 'collects the definition' );
	t.ok( record.astPath.length > 1, 'accounts for the nested source node' );
	t.strictEqual( value.indexOf( '"type":"definition"' ), -1, 'omits it from projected MDAST' );
	t.notEqual( value.indexOf( 'https://example.com' ), -1, 'resolves the nested reference' );
	t.end();
});

tape( 'the schema rejects incomplete type-specific nodes', function test( t ) {
	var markdown;
	var code;
	var doc;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'```javascript',
		'1',
		'```'
	].join( '\n' );
	doc = parseJSON( JSON.stringify( convert( markdown ) ) );
	code = findNodes( doc.children, 'code' )[ 0 ];

	delete code.execution;
	t.ok( validateDocument( doc ).length > 0, 'returns validation errors' );
	t.end();
});

tape( 'the function ensures that out-of-hierarchy section headings close active topics in source order', function test( t ) {
	var markdown;
	var children;
	var section;
	var doc;

	markdown = [
		'# Beep',
		'',
		'> Boop!',
		'',
		'<section class="usage">',
		'',
		'## Usage',
		'',
		'#### beep( x )',
		'',
		'Topic prose.',
		'',
		'## Appendix',
		'',
		'Following prose.',
		'',
		'</section>',
		'',
		'<!-- /.usage -->'
	].join( '\n' );
	doc = convert( markdown );
	section = findSection( doc.children, 'usage' );
	children = section.children;

	t.strictEqual( children[ 1 ].type, 'topic', 'creates the API topic' );
	t.strictEqual( children[ 2 ].type, 'heading', 'places the out-of-hierarchy heading in the section' );
	t.strictEqual( children[ 3 ].type, 'markdown', 'places following prose after the direct heading' );

	t.ok( children[ 1 ].children[ 1 ].source.envelope.end.offset <= children[ 2 ].source.envelope.start.offset, 'keeps depth-first leaf ranges monotonic' );
	t.ok( children[ 2 ].source.envelope.end.offset <= children[ 3 ].source.envelope.start.offset, 'keeps following prose in source order' );
	t.end();
});
